-- composition of rule kernels L:eliminate_outer_join x P:ProjectionPushdown (datafusion), template cte_twice
WITH ka AS (SELECT a2.c5 AS c0, a2.c2 AS c1 FROM (ti AS a1 LEFT JOIN t3 AS a2 ON (a1.c1 = a2.c5)) WHERE a2.c1), kb AS (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a2.c3, a1.c0 UNION ALL (SELECT '2024-01-01'::date AS c0 UNION SELECT '2000-01-01'::date AS c0)) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (SELECT a2.c5 AS c0, a2.c2 AS c1 FROM (ti AS a1 LEFT JOIN t3 AS a2 ON (a1.c1 = a2.c5)) WHERE a2.c1) AS ka) + (SELECT count(*) FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a2.c3, a1.c0 UNION ALL (SELECT '2024-01-01'::date AS c0 UNION SELECT '2000-01-01'::date AS c0)) AS kb)
